@php($staffIds=$registers->staff(auth()->user())->pluck('id'))
<section class="br-table-section"><h4 class="font-semibold">Approved KPI Register</h4><a class="hr-report-control" href="{{ route('portal.performance.index') }}">KPI targets &amp; performance tools</a><div class="br-table-wrap"><table class="br-table"><thead><tr><th>Staff / department</th><th>KPI</th><th>Period</th><th>Target</th><th>Weight</th></tr></thead><tbody>@foreach(\App\Models\PerformanceTargetPlan::with(['owner:id,name','kpi'])->whereNotNull('approved_at')->whereNull('withdrawn_at')->where(fn($q)=>$q->whereIn('owner_id',$staffIds)->orWhere(fn($d)=>$d->whereNull('owner_id')->when(!$full,fn($q)=>$q->whereIn('department',\App\Models\User::departmentAliases(auth()->user()->department)))))->whereDate('period_start','<=',$to)->whereDate('period_end','>=',$from)->get() as $plan)<tr><td>{{ $plan->owner?->name??\App\Models\User::departmentLabel($plan->department) }}</td><td>{{ $plan->kpi?->name }}</td><td>{{ $plan->period_start->toDateString() }} – {{ $plan->period_end->toDateString() }}</td><td>{{ $plan->target }}</td><td>{{ $plan->weight }}%</td></tr>@endforeach</tbody></table></div></section>
<section class="br-table-section"><h4 class="font-semibold">Portal Appraisals</h4><div class="br-table-wrap"><table class="br-table"><thead><tr><th>Staff</th><th>Period</th><th>Score</th><th>Status</th></tr></thead><tbody>@foreach($registers->appraisals(auth()->user(),$from,$to) as $appraisal)<tr><td>{{ $appraisal->user?->name }}</td><td>{{ $appraisal->year }} · {{ $appraisal->quarter }}</td><td>{{ $appraisal->status==='approved'?$appraisal->final_score:'Awaiting final approval' }}</td><td>{{ $appraisal->status_label }}</td></tr>@endforeach</tbody></table></div></section>
